import{_ as e,c as r,o as t,af as i}from"./chunks/framework.BKhkn9_V.js";const _=JSON.parse('{"title":"北京一日游","description":"","frontmatter":{},"headers":[],"relativePath":"pages/20251110.md","filePath":"pages/20251110.md"}'),h={name:"pages/20251110.md"};function l(n,a,o,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="北京一日游" tabindex="-1">北京一日游 <a class="header-anchor" href="#北京一日游" aria-label="Permalink to “北京一日游”">​</a></h1><p>2025年11月8日，与好友去北京游玩，一天下来颇有意思，简单描述下。</p><h2 id="开始" tabindex="-1">开始 <a class="header-anchor" href="#开始" aria-label="Permalink to “开始”">​</a></h2><p>他俩的计划是去颐和园，我们想去地坛，加上时间不一样。所以，分开走吧。</p><h2 id="到达" tabindex="-1">到达 <a class="header-anchor" href="#到达" aria-label="Permalink to “到达”">​</a></h2><p>到了地坛之后，看到公园中好多人拍照，但不知道拍什么，遂我俩也跟着拍。<br> 后来看到好些树，书上有认养人的名字，我心中也想认养一个，价格倒是不贵，普通的50元一颗。<br> 看Wiki百科上说，地坛是用来祭祀的，所以我在找那个最大的建筑。<br> 后来看到方泽坛就是想去的地方，每人花了5元门票，去到里面，拍了拍照，看了看建筑的样式</p><h2 id="使领馆" tabindex="-1">使领馆 <a class="header-anchor" href="#使领馆" aria-label="Permalink to “使领馆”">​</a></h2><p>我觉得各国在京的使领馆是一个不一样的风景和氛围，然后我俩去了亮马桥，参观了下各个国家的使馆建筑。</p><h2 id="豆子胡同" tabindex="-1">豆子胡同 <a class="header-anchor" href="#豆子胡同" aria-label="Permalink to “豆子胡同”">​</a></h2><p>来这是为了打卡《魔幻手机》的拍摄地&quot;圣地迅游&quot;</p><h2 id="南锣鼓巷" tabindex="-1">南锣鼓巷 <a class="header-anchor" href="#南锣鼓巷" aria-label="Permalink to “南锣鼓巷”">​</a></h2><h2 id="什刹海" tabindex="-1">什刹海 <a class="header-anchor" href="#什刹海" aria-label="Permalink to “什刹海”">​</a></h2><h2 id="露台酒吧" tabindex="-1">露台酒吧 <a class="header-anchor" href="#露台酒吧" aria-label="Permalink to “露台酒吧”">​</a></h2><p>略...</p>',14)])])}const b=e(h,[["render",l]]);export{_ as __pageData,b as default};
